    static String canonicalPhone(String raw)throws IOException{if(raw==null)throw new IOException("请输入正确的11位中国大陆手机号");String phone=raw.trim();if(phone.startsWith("+86"))phone=phone.substring(3);else if(phone.startsWith("86")&&phone.length()==13)phone=phone.substring(2);if(!phone.matches("1[3-9][0-9]{9}"))throw new IOException("请输入正确的11位中国大陆手机号");return "+86"+phone;}
